/**
 * Imagery-only trial-type instruction screen (I-only).
 *
 * Audience: general-public Prolific participants. Copy is plain English —
 * no jargon like "set size", "probe", "encoding", "stimulus", "imagery
 * maintenance", or "rotated mental representation". The participant is
 * asked, in normal language, to (a) keep the pattern in mind that they
 * just learned in the demo, (b) turn it the way the arrow shows, and
 * (c) decide whether each star is on-pattern or not on-pattern relative
 * to that turned pattern.
 *
 * Visual frame language (matches the memory screens): the participant
 * only ever sees the bull's-eye circle. The 5×5 cell grid is invisible.
 * Copy therefore says "inside the circle" / "location" instead of "on
 * the grid" / "square", and never tells the participant which square
 * the star is on — only whether it lands on the rotated pattern.
 *
 * The non-trivial design constraint to communicate is **rotation**: the
 * star's on/off-pattern membership is judged against the *rotated*
 * mental pattern, not the upright one. The rotation-cue arrow is shown
 * here (and in I+D / I+T) precisely because imagery is involved —
 * without an imagery component there is nothing to rotate, so D-only and
 * T-only screens never mention the cue. The specific rotation angle is
 * NOT written into the copy: the arrow alone tells the participant
 * which way to turn the pattern, mirroring the reference experiment.
 *
 * Pagination: the long instruction text is delivered as a sequence of
 * short pages through the jsPsych instructions plugin so the participant
 * sees one piece at a time. Space (or Next) advances; Left arrow
 * (or Previous) goes back. The last page advances out of the trial and
 * into the per-type demo.
 */
import jsPsychInstructions from '@jspsych/plugin-instructions';
import { config } from '../config.js';
import { registerInstructionFactory, trackInstructionNode } from '../hidden-nav.js';
import { slideTextPage } from '../visuals/slide-layout.js';

/* See `slide-layout.js` for the unification rationale — the H2 title
 * and the plugin's Previous/Next nav land at the same y across every
 * page of every deck (and across the calibration intros and the five
 * demo screens) because every wrapper shares the same `min-height`. */
const FEEDBACK_GREEN = `<span style="color: #34d399;"><strong>green</strong></span>`;
const FEEDBACK_RED = `<span style="color: #f87171;"><strong>red</strong></span>`;
const CALLOUT_OPEN = `<p style="border-left: 3px solid #772139; padding: 0.5rem 0.75rem; margin: 1rem 0; background: rgba(119, 33, 57, 0.08);">`;

const NAV_OPTS = Object.freeze({
  key_forward: ' ',
  key_backward: 'ArrowLeft',
  allow_backward: true,
  allow_keys: true,
  show_clickable_nav: true,
  show_page_number: true,
  page_label: 'Page',
  button_label_previous: 'Previous',
  button_label_next: 'Next',
});

export function iOnlyInstructionNode() {
  const starsPerTrial = config.imagery.stars_per_trial;
  const title = 'Task 3 — Picture the pattern';
  const pages = [
    slideTextPage({
      title,
      body: `
        <p>In this task we will ask you to <strong>picture a pattern in
        your mind</strong> and to keep that picture clear while you
        respond.</p>
        ${CALLOUT_OPEN}
        <strong style="color: #772139;">Important:</strong> you will see
        the pattern in the demonstration just before the practice —
        please pay close attention to it then, because the pattern will
        <strong>not</strong> be shown again during the trials.</p>
      `,
      narration: `Welcome to Task 3. In this task, we will ask you to picture a pattern in your mind, and to keep that picture clear while you respond. Important: you will see the pattern in the demonstration just before the practice — please pay close attention to it then, because the pattern will not be shown again during the trials.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>On each trial, an <strong>arrow</strong> will briefly appear.
        The arrow tells you to <strong>turn the pattern in your
        mind</strong> in the direction it points, like rotating a piece
        of paper. Hold this turned pattern in mind.</p>
      `,
      narration: `Here's how each trial starts. On each trial, an arrow will briefly appear. The arrow tells you to turn the pattern in your mind in the direction it points, like rotating a piece of paper. Hold this turned pattern in mind.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>Then <strong>${starsPerTrial} bright stars</strong> will flash
        inside the circle, one at a time. For each star, decide whether
        it lands in a location that would be <strong>covered by the
        rotated pattern you are picturing</strong>.</p>
        <p style="margin: 1.25rem 0;">
          Press <strong>On-pattern</strong> if the star falls on your
          pictured pattern.<br />
          Press <strong>Not on-pattern</strong> if it does not.
        </p>
      `,
      narration: `Then ${starsPerTrial} bright stars will flash inside the circle, one at a time. For each star, decide whether it lands in a location that would be covered by the rotated pattern you are picturing. Press On-pattern if the star falls on your pictured pattern. Press Not on-pattern if it does not.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>You will have <strong>3 seconds</strong> for each star. Try to
        get it right rather than answer quickly, but please don't take
        too long either.</p>
        <p>If you answer in time, the star can turn
        ${FEEDBACK_GREEN} if you were correct or
        ${FEEDBACK_RED} if you were not. This colour change happens while
        the star is still on the screen, so you can learn from each
        star.</p>
        <p>Be honest about what you actually "see" in your mind. If your
        picture is fuzzy, just do your best — there is no expectation of
        a perfect mental picture.</p>
        <p style="text-align: center; margin-top: 1.5rem;">
          Press <kbd>Space</kbd> to start the practice for Task 3.
        </p>
      `,
      narration: `A few more things to know. You will have 3 seconds for each star. Try to get it right rather than answer quickly, but please don't take too long either. If you answer in time, the star can turn green if you were correct, or red if you were not. This colour change happens while the star is still on the screen, so you can learn from each star. Be honest about what you actually see in your mind. If your picture is fuzzy, just do your best — there is no expectation of a perfect mental picture. When you're ready, press Space to start the practice for Task 3.`,
    }),
  ];
  const node = {
    type: jsPsychInstructions,
    pages,
    ...NAV_OPTS,
    data: { phase: 'instructions_imagery_i_only' },
  };
  registerInstructionFactory(node.data.phase, iOnlyInstructionNode);
  return trackInstructionNode(node);
}

/* Backward-compat shim — used by tests and any consumer that wants the
 * imagery instructions as an array. New consumers should prefer
 * `iOnlyInstructionNode()`. */
export function imageryInstructionNodes() {
  return [iOnlyInstructionNode()];
}
