/**
 * Dual-task trial-type instruction screens (I+D and I+T).
 *
 * Audience: general-public Prolific participants. Copy is plain English —
 * "remember the dots", "picture the pattern", "turn it the way the arrow
 * shows". Avoids jargon like "encoding stream", "interleaved", "subtask",
 * "mental image", "concurrent maintenance", "cognitive load", etc.
 *
 * Visual frame language (matches the memory and imagery screens): the
 * participant only ever sees the bull's-eye circle. The 5×5 cell grid is
 * invisible. Copy therefore says "inside the circle" / "location"
 * instead of "on the grid" / "square".
 *
 * Each screen teaches one dual-task type and emphasises three things:
 * (a) the rotation cue arrow tells the participant which way to turn
 * the pictured pattern in mind — exactly as in I-only; (b) dots/tones
 * and stars come mixed in together within one trial; and (c) keeping
 * the pictured pattern in mind for the WHOLE trial is critical, with a
 * single permitted "drop the image" moment when the central question
 * mark appears for the recognition tests at the end of the trial.
 *
 * The rotation cue is mentioned ONLY here and in `imagery.js` (I-only).
 * D-only and T-only screens deliberately do not mention it: in those
 * trials no rotation arrow is shown to the participant, because there
 * is nothing to picture or turn. The grid layout that would be rotated
 * still exists in the abstract experimental design across all five
 * trial types, but the participant only ever sees the arrow on
 * imagery-bearing trials. The specific rotation angle is NOT written
 * into the copy — the arrow alone does the job, mirroring the
 * reference experiment.
 *
 * Pagination: the long instruction text is delivered as a sequence of
 * short pages through the jsPsych instructions plugin so the participant
 * sees one piece at a time. Space (or Next) advances; Left arrow
 * (or Previous) goes back. The last page advances out of the trial and
 * into the per-type demo.
 */
import jsPsychInstructions from '@jspsych/plugin-instructions';
import { config } from '../config.js';
import { registerInstructionFactory, trackInstructionNode } from '../hidden-nav.js';
import { slideTextPage } from '../visuals/slide-layout.js';

/* See `slide-layout.js` for the unification rationale — the H2 title
 * and the plugin's Previous/Next nav land at the same y across every
 * page of every deck (and across the calibration intros and the five
 * demo screens) because every wrapper shares the same `min-height`. */
const FEEDBACK_GREEN = `<span style="color: #34d399;"><strong>green</strong></span>`;
const FEEDBACK_RED = `<span style="color: #f87171;"><strong>red</strong></span>`;
const CALLOUT_OPEN = `<p style="border-left: 3px solid #772139; padding: 0.5rem 0.75rem; margin: 1rem 0; background: rgba(119, 33, 57, 0.08);">`;

const NAV_OPTS = Object.freeze({
  key_forward: ' ',
  key_backward: 'ArrowLeft',
  allow_backward: true,
  allow_keys: true,
  show_clickable_nav: true,
  show_page_number: true,
  page_label: 'Page',
  button_label_previous: 'Previous',
  button_label_next: 'Next',
});

export function iDInstructionNode() {
  const setSize = config.memory.set_size;
  const starsPerTrial = config.imagery.stars_per_trial;
  const totalEvents = setSize + starsPerTrial;
  const title = 'Task 4 — Dots and pattern together';
  const pages = [
    slideTextPage({
      title,
      body: `
        <p>This task combines Task 3 (the pattern) with Task 1 (the
        dots). Each trial begins with the <strong>arrow</strong>, which
        tells you to turn the pattern in your mind. Hold this turned
        pattern in mind for the whole trial.</p>
      `,
      narration: `Now on to Task 4. This task combines Task 3, the pattern, with Task 1, the dots. Each trial begins with the arrow, which tells you to turn the pattern in your mind. Hold this turned pattern in mind for the whole trial.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>Then <strong>${totalEvents} things</strong> will appear inside
        the circle one at a time, all <strong>mixed together</strong>:</p>
        <ul style="margin: 0.75rem 1.25rem;">
          <li><strong>${starsPerTrial} stars</strong> — for each star,
          decide whether it lands in a location that would be covered by
          the rotated pattern you are picturing (just like Task 3).
          Press <strong>On-pattern</strong> if the star falls on your
          pictured pattern, or <strong>Not on-pattern</strong> if it
          does not.</li>
          <li><strong>${setSize} dots</strong> — try to remember
          <strong>which locations</strong> the dots appear in, so you
          can answer the dot tests at the end of the trial (just like
          Task 1).</li>
        </ul>
      `,
      narration: `Then ${totalEvents} things will appear inside the circle one at a time, all mixed together. ${starsPerTrial} stars — for each star, decide whether it lands in a location that would be covered by the rotated pattern you are picturing, just like Task 3. Press On-pattern if the star falls on your pictured pattern, or Not on-pattern if it does not. And ${setSize} dots — try to remember which locations the dots appear in, so you can answer the dot tests at the end of the trial, just like Task 1.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>After the ${totalEvents} things, we will test your dot memory
        <strong>${setSize} times</strong>. Each time, a white dot will be
        shown for 3 seconds in some location:</p>
        <p style="margin: 1.25rem 0;">
          Press <strong>Yes</strong> if
          <em>a dot was presented here</em>.<br />
          Press <strong>No</strong> if
          <em>no dot was presented here</em>.
        </p>
        <p>You will have <strong>3 seconds</strong> for each star and for
        each dot test. If you answer in time, the star or dot can turn
        ${FEEDBACK_GREEN} if you were correct or
        ${FEEDBACK_RED} if you were not while it is still on the screen,
        so you can learn from each response.</p>
      `,
      narration: `After the ${totalEvents} things, we will test your dot memory ${setSize} times. Each time, a white dot will be shown for 3 seconds in some location. Press Yes if a dot was presented here. Press No if no dot was presented here. You will have 3 seconds for each star and for each dot test. If you answer in time, the star or dot can turn green if you were correct, or red if you were not, while it is still on the screen, so you can learn from each response.`,
    }),
    slideTextPage({
      title,
      body: `
        ${CALLOUT_OPEN}
        <strong style="color: #772139;">VERY important:</strong> keep the
        picture of the rotated pattern in your mind during the
        <strong>entire</strong> trial. The only moment you may let the
        picture go is when the central
        <strong>question mark (?)</strong> appears — that is when the
        dot tests begin, and at that point you can drop the image and
        focus only on the dot tests.</p>
        <p style="text-align: center; margin-top: 1.5rem;">
          Press <kbd>Space</kbd> to start the practice for Task 4.
        </p>
      `,
      narration: `One last thing, and this is very important. Keep the picture of the rotated pattern in your mind during the entire trial. The only moment you may let the picture go is when the central question mark appears — that is when the dot tests begin, and at that point you can drop the image and focus only on the dot tests. When you're ready, press Space to start the practice for Task 4.`,
    }),
  ];
  const node = {
    type: jsPsychInstructions,
    pages,
    ...NAV_OPTS,
    data: { phase: 'instructions_dual_i_d' },
  };
  registerInstructionFactory(node.data.phase, iDInstructionNode);
  return trackInstructionNode(node);
}

