/**
 * Memory-only trial-type instruction screens (D-only, T-only).
 *
 * Audience: general-public Prolific participants — not psychology students.
 * Copy is deliberately plain English: "remember where each dot was", "do you
 * recognise this tone", etc., avoiding jargon like "set size", "encoding
 * stream", "probe", "retention", "imagery", etc.
 *
 * Importantly, NEITHER screen mentions a rotation cue: rotation is an
 * imagery-only construct. The grid layout that would be rotated still
 * exists in the abstract design, but on D-only and T-only trials the
 * participant is not asked to imagine anything, so no arrow appears on
 * the screen and no rotation step occurs in the trial sequence.
 *
 * Visual frame language: the participant only ever sees the bull's-eye
 * circle (the round-1 reference's `#grid-circle`) — the underlying 5×5
 * cell grid is invisible to participants throughout the task. Copy
 * therefore says "inside the circle" / "location" instead of "on the
 * grid" / "square", to match what the participant actually sees.
 *
 * Pagination: each instruction screen is split into several short pages
 * delivered through the jsPsych instructions plugin so the participant
 * sees one piece of the rules at a time and can step back if they missed
 * something. Space (or the on-screen Next button) advances; Left arrow
 * (or Previous) goes back. The last page advances out of the trial and
 * into the per-type demo.
 */
import jsPsychInstructions from '@jspsych/plugin-instructions';
import { config } from '../config.js';
import { registerInstructionFactory, trackInstructionNode } from '../hidden-nav.js';
import { slideTextPage } from '../visuals/slide-layout.js';

/* Each page uses the shared text-slide wrapper from `slide-layout.js`,
 * which pins the H2 title at the top and lets body copy fill whatever
 * remains, so the plugin's Previous/Next nav lands at the same y across
 * every page of every deck — and across the calibration intros, the
 * imagery / dual decks, and the five demo screens. See `slide-layout.js`
 * for the unification rationale. The H2 inside the title row is rendered
 * by the primitive itself; pages here only supply the title text and the
 * body HTML. */
const FEEDBACK_GREEN = `<span style="color: #34d399;"><strong>green</strong></span>`;
const FEEDBACK_RED = `<span style="color: #f87171;"><strong>red</strong></span>`;

const NAV_OPTS = Object.freeze({
  key_forward: ' ',
  key_backward: 'ArrowLeft',
  allow_backward: true,
  allow_keys: true,
  show_clickable_nav: true,
  show_page_number: true,
  page_label: 'Page',
  button_label_previous: 'Previous',
  button_label_next: 'Next',
});

export function dOnlyInstructionNode() {
  const setSize = config.memory.set_size;
  const title = 'Task 1 — Remember the dots';
  const pages = [
    slideTextPage({
      title,
      body: `
        <p>You will see <strong>${setSize} dots</strong> appear one at a
        time at different locations inside a circle on the screen. Each
        dot is shown briefly. Try to remember
        <strong>which locations</strong> the dots appear in.</p>
      `,
      narration: `Welcome to Task 1. In this first task, you will see ${setSize} dots appear one at a time at different locations inside a circle on the screen. Each dot is shown briefly. Try to remember which locations the dots appear in.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>After the dots, we will test your memory <strong>${setSize}
        times</strong>. Each time, a white dot will be shown for
        3 seconds, and you have to say whether the dot was shown in
        that location.</p>
        <p>Just keep watching the centre of the circle and remember
        each dot whenever it appears.</p>
      `,
      narration: `After the dots, we will test your memory ${setSize} times. Each time, a white dot will be shown for 3 seconds, and you have to say whether the dot was shown in that location. Just keep watching the centre of the circle, and remember each dot whenever it appears.`,
    }),
    slideTextPage({
      title,
      body: `
        <p style="margin: 1.25rem 0;">
          Press <strong>Yes</strong> if you remember you saw a dot in
          that location.<br />
          Press <strong>No</strong> if you did not.
        </p>
        <p>You will have <strong>3 seconds</strong> to provide your
        response. Try to get it right rather than answer quickly, but
        please don't take too long either.</p>
      `,
      narration: `Now for the responses. Press Yes if you remember you saw a dot in that location. Press No if you did not. You will have 3 seconds to provide your response. Try to get it right rather than answer quickly, but please don't take too long either.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>If you answer in time, the dot can turn
        ${FEEDBACK_GREEN} if you were correct or
        ${FEEDBACK_RED} if you were not. This colour change happens while
        the dot is still on the screen, so you can learn from each
        test.</p>
        <p>You will now do a short practice for this task before moving
        on to the next.</p>
        <p style="text-align: center; margin-top: 1.5rem;">
          Press <kbd>Space</kbd> to start the practice for Task 1.
        </p>
      `,
      narration: `One last thing. If you answer in time, the dot can turn green if you were correct, or red if you were not. This colour change happens while the dot is still on the screen, so you can learn from each test. You will now do a short practice for this task before moving on to the next. When you're ready, press Space to start the practice for Task 1.`,
    }),
  ];
  const node = {
    type: jsPsychInstructions,
    pages,
    ...NAV_OPTS,
    data: { phase: 'instructions_memory_d_only' },
  };
  registerInstructionFactory(node.data.phase, dOnlyInstructionNode);
  return trackInstructionNode(node);
}

export function tOnlyInstructionNode() {
  const setSize = config.memory.set_size;
  const title = 'Task 2 — Remember the tones';
  const pages = [
    slideTextPage({
      title,
      body: `
        <p>This task works just like Task 1, but now you will hear sounds
        instead of seeing dots. You will hear <strong>${setSize} short
        tones</strong>, one at a time. Try to remember
        <strong>each tone you hear</strong>.</p>
      `,
      narration: `Now on to Task 2. This task works just like Task 1, but now you will hear sounds instead of seeing dots. You will hear ${setSize} short tones, one at a time. Try to remember each tone you hear.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>After the ${setSize} tones, we will play <strong>${setSize}
        more tones, one at a time</strong>. Each time, decide whether
        that tone was one of the ones you just heard.</p>
        <p>You don't need to look at anything during this task — just
        keep your eyes on the centre of the circle and listen for
        each tone whenever it plays.</p>
      `,
      narration: `After the ${setSize} tones, we will play ${setSize} more tones, one at a time. Each time, decide whether that tone was one of the ones you just heard. You don't need to look at anything during this task — just keep your eyes on the centre of the circle, and listen for each tone whenever it plays.`,
    }),
    slideTextPage({
      title,
      body: `
        <p style="margin: 1.25rem 0;">
          Press <strong>Yes</strong> if you heard this tone before.<br />
          Press <strong>No</strong> if you did not.
        </p>
        <p>You will have <strong>3 seconds</strong> to provide your
        response. If you answer in time, the central question mark can
        change colour while it is still on the screen:
        it turns ${FEEDBACK_GREEN} if you were correct or
        ${FEEDBACK_RED} if you were not, so you can learn from each
        test.</p>
      `,
      narration: `Here are the responses. Press Yes if you heard this tone before. Press No if you did not. You will have 3 seconds to provide your response. If you answer in time, the central question mark can change colour while it is still on the screen: it turns green if you were correct, or red if you were not, so you can learn from each test.`,
    }),
    slideTextPage({
      title,
      body: `
        <p>Please make sure your audio volume is still at the level you
        set earlier.</p>
        <p style="text-align: center; margin-top: 1.5rem;">
          Press <kbd>Space</kbd> to start the practice for Task 2.
        </p>
      `,
      narration: `One quick reminder. Please make sure your audio volume is still at the level you set earlier. When you're ready, press Space to start the practice for Task 2.`,
    }),
  ];
  const node = {
    type: jsPsychInstructions,
    pages,
    ...NAV_OPTS,
    data: { phase: 'instructions_memory_t_only' },
  };
  registerInstructionFactory(node.data.phase, tOnlyInstructionNode);
  return trackInstructionNode(node);
}

/* Backward-compat shim — used by tests that exercise the memory teaching
 * pair as a unit. New consumers should prefer the per-type accessors. */
export function memoryInstructionNodes() {
  return [dOnlyInstructionNode(), tOnlyInstructionNode()];
}
