/**
 * Brief pre-instruction gate: participant confirms readiness, then hears
 * 10 × 1 s sine tones (uniform random frequency ∈ [500 Hz, 2000 Hz]),
 * separated by 200 ms silence. Screen is cleared during playback so only
 * audio is presented.
 */
import htmlButtonResponse from '@jspsych/plugin-html-button-response';
import callFunction from '@jspsych/plugin-call-function';

import { playSineTone } from '../audio/dsp.js';
import { equalLoudnessGainDb70Phon } from '../audio/equal-loudness.js';
import { getSessionPRNG } from '../prng.js';
import { registerHiddenNavStep, trackHiddenNavNode } from '../hidden-nav.js';

const N_TONES = 10;
const TONE_MS = 1000;
const GAP_MS = 200;
const FREQ_MIN_HZ = 500;
const FREQ_MAX_HZ = 2000;
const COSINE_RAMP_MS = 30;

function uniformFreqHz(prng) {
  return FREQ_MIN_HZ + prng.next() * (FREQ_MAX_HZ - FREQ_MIN_HZ);
}

async function playSeries(freqsHz) {
  for (let i = 0; i < freqsHz.length; i++) {
    const f = freqsHz[i];
    await playSineTone(f, {
      durationMs: TONE_MS,
      rampMs: COSINE_RAMP_MS,
      gainDb: equalLoudnessGainDb70Phon(f),
    });
    if (i < freqsHz.length - 1) {
      await new Promise((r) => setTimeout(r, GAP_MS));
    }
  }
}

function readyTrial() {
  const stepId = 'ready_random_tones_gate';
  const node = {
    type: htmlButtonResponse,
    stimulus: `
      <div style="max-width: 36rem; margin: 2rem auto; text-align: center;">
        <p style="font-size: 1.35rem;">Are you ready?</p>
      </div>
    `,
    choices: ['ready'],
    data: { phase: 'ready_random_tones_gate' },
  };
  registerHiddenNavStep(stepId, readyTrial);
  return trackHiddenNavNode(node, stepId);
}

function tonePlaybackTrial() {
  const stepId = 'ready_random_tones_playback';
  const node = {
    type: callFunction,
    async: true,
    data: { phase: 'ready_random_tone_sequence' },
    func: (done) => {
      const prng = getSessionPRNG();
      const freqs_hz = Array.from({ length: N_TONES }, () => uniformFreqHz(prng));
      window.jsPsych.getDisplayElement().innerHTML = '';

      playSeries(freqs_hz)
        .then(() =>
          done({
            freqs_hz,
            tone_ms: TONE_MS,
            gap_ms: GAP_MS,
            freq_min_hz: FREQ_MIN_HZ,
            freq_max_hz: FREQ_MAX_HZ,
          })
        )
        .catch((err) => {
          console.error('[ready_random_tones] playback failed', err);
          done({
            freqs_hz,
            error: String(err?.message ?? err),
            tone_ms: TONE_MS,
            gap_ms: GAP_MS,
          });
        });
    },
  };
  registerHiddenNavStep(stepId, tonePlaybackTrial);
  return trackHiddenNavNode(node, stepId);
}

export function assembleReadyRandomTonesTimeline() {
  return [readyTrial(), tonePlaybackTrial()];
}
