/**
 * VVIQ-2 — Marks's (1995) Vividness of Visual Imagery Questionnaire,
 * extended version. 32 items grouped into 8 vignettes (4 items each),
 * rated on Marks's 1995 5-point clarity scale:
 *
 *   5 = Perfectly clear and as vivid as normal vision
 *   4 = Clear and reasonably vivid
 *   3 = Moderately clear and vivid
 *   2 = Vague and dim
 *   1 = No image at all; you only "know" that you are thinking of the object
 *
 * Note that the 1995 revision **reverses the scale direction** relative to
 * the 1973 16-item original: in VVIQ-2, _higher_ = more vivid (composite
 * range 32–160). This direction is the one promoted on Marks's own
 * `davidfmarks.net` reference page and matches contemporary validation
 * studies (Campos 2011; Jankowska & Karwowski 2023).
 *
 * Scoring convention. We store the **raw VVIQ-2 codes** (1–5 with 5 = most
 * vivid) in the data record; the `scoreVviq` helper exposes both the
 * canonical VVIQ-2 total (`vviq2Total`, higher = more vivid) and an
 * inverted total (`vviq2InvertedTotal` = Σ(6 − raw), lower = more vivid)
 * so an analysis pipeline that prefers the historic Marks 1973 direction
 * can pick that without re-coding.
 *
 * Source. Wording below is taken verbatim from David F. Marks's own
 * reference reproduction at https://davidfmarks.net/vividness-of-visual-imagery-questionnaire-2/
 * (which states "Researchers and interested individuals are free to use
 * this questionnaire without seeking permission from the author"). The
 * original publication is Marks, D. F. (1995). New directions for mental
 * imagery research. *Journal of Mental Imagery*, 19(3–4), 153–167. The
 * 8-vignette structure (the 4 Marks 1973 scenes + 4 new scenes: highway,
 * beach, railway station, garden) matches the lineage of this lab's
 * Project 1 Persian instrument (`mental_imagery_questionnaire.html`,
 * titled "پرسشنامه وضوح تصویرسازی ذهنی 1995"), which was the back-translation
 * reference cited in PLAN §7 q7 prior to the 2026-05-11 swap.
 *
 * Decision log: PLAN §7 q7 originally recommended Marks 1973 verbatim;
 * 2026-05-11 design revision upgraded to VVIQ-2 (Marks 1995) to match the
 * Project 1 Persian instrument's lineage and pick up the validated
 * 32-item composite (Cronbach α reported ≥ .91 across Campos 2011,
 * Morrison & Wallace 2001, Jankowska & Karwowski 2023).
 */
import surveyHtmlForm from '@jspsych/plugin-survey-html-form';
import { registerHiddenNavStep, trackHiddenNavNode } from '../hidden-nav.js';

export const VVIQ_SCALE = Object.freeze([
  Object.freeze({
    value: 1,
    label: 'No image at all; you only "know" that you are thinking of the object',
  }),
  Object.freeze({ value: 2, label: 'Vague and dim' }),
  Object.freeze({ value: 3, label: 'Moderately clear and vivid' }),
  Object.freeze({ value: 4, label: 'Clear and reasonably vivid' }),
  Object.freeze({ value: 5, label: 'Perfectly clear and as vivid as normal vision' }),
]);

