const VVIQ_TOTAL_ITEMS = VVIQ_VIGNETTES.reduce((acc, v) => acc + v.items.length, 0);

if (VVIQ_TOTAL_ITEMS !== 32) {
  throw new Error(`VVIQ_VIGNETTES must contain exactly 32 items, got ${VVIQ_TOTAL_ITEMS}`);
}

/**
 * Render one vignette as a survey-html-form. Each item is a `<select>` so
 * keyboard-only navigation works (radio groups in HTML are clunky to label
 * when there are 5 options with long text). The select's `name=` attribute
 * uses the item id, which is also what we recover in `on_finish` below.
 *
 * @param {object} vignette  one entry from `VVIQ_VIGNETTES`
 * @returns {object}         jsPsych timeline node
 */
function vviqVignetteNode(vignette) {
  const itemRows = vignette.items
    .map((item) => {
      const optionsHtml = VVIQ_SCALE.map(
        (s) => `<option value="${s.value}">${s.value} — ${s.label}</option>`
      ).join('');
      return `
        <tr>
          <td style="padding: 0.5rem 0.75rem 0.5rem 0; vertical-align: top;">${item.text}</td>
          <td style="padding: 0.5rem 0; vertical-align: top;">
            <select name="${item.id}" required>
              <option value="">—</option>
              ${optionsHtml}
            </select>
          </td>
        </tr>`;
    })
    .join('');
  const partNumber = VVIQ_VIGNETTES.findIndex((v) => v.id === vignette.id) + 1;
  const stepId = vignette.id;
  const node = {
    type: surveyHtmlForm,
    preamble: `
      <h2>Imagery questionnaire (part ${partNumber} of ${VVIQ_VIGNETTES.length})</h2>
      <p style="max-width: 40rem; margin: 0.5rem auto; text-align: left;">
        ${vignette.preamble}
      </p>
      <p style="max-width: 40rem; margin: 0.5rem auto; text-align: left;">
        For each item below, rate the vividness of the image that comes to mind.
      </p>
    `,
    html: `
      <div style="max-width: 44rem; margin: 0 auto;">
        <table style="width: 100%; border-collapse: collapse; text-align: left;">
          ${itemRows}
        </table>
      </div>
    `,
    button_label: 'Continue',
    on_finish: (data) => {
      data.phase = 'vviq';
      data.vviq_vignette_id = vignette.id;
      data.vviq_responses = vignette.items.reduce((acc, item) => {
        const raw = data.response?.[item.id];
        acc[item.id] = raw === '' || raw === null || raw === undefined ? null : Number(raw);
        return acc;
      }, {});
    },
  };
  registerHiddenNavStep(stepId, () => vviqVignetteNode(vignette));
  return trackHiddenNavNode(node, stepId);
}

/**
 * Returns the eight-vignette VVIQ-2 timeline. Splice into the runner after
 * Main B and before the upload node.
 */
export function vviqTimeline() {
  return VVIQ_VIGNETTES.map(vviqVignetteNode);
}

/**
 * Score a set of VVIQ-2 rows. Computes both the canonical VVIQ-2 total
 * (higher = more vivid) and an inverted total (lower = more vivid, for
 * analyses that prefer the historic Marks 1973 direction). Returns null
 * for both when any of the 32 items is missing — the analyst should
 * decide how to handle partials, not us.
 *
 * @param {object[]} rows                jsPsych data rows (any phase)
 * @returns {{
 *   itemResponses: Record<string, number|null>,
 *   answered: number,
 *   total: number,
 *   vviq2Total: number|null,
 *   vviq2InvertedTotal: number|null,
 *   complete: boolean
 * }}
 */
export function scoreVviq(rows) {
  const vviqRows = (rows ?? []).filter((r) => r?.phase === 'vviq');
  const itemResponses = {};
  for (const v of VVIQ_VIGNETTES) {
    for (const item of v.items) itemResponses[item.id] = null;
  }
  for (const row of vviqRows) {
    const responses = row.vviq_responses ?? {};
    for (const [k, v] of Object.entries(responses)) {
      if (k in itemResponses && Number.isFinite(v)) itemResponses[k] = v;
    }
  }
  const answered = Object.values(itemResponses).filter((v) => v !== null).length;
  const complete = answered === VVIQ_TOTAL_ITEMS;
  /* Canonical VVIQ-2 (Marks 1995): higher = more vivid; range 32..160. */
  const vviq2Total = complete ? Object.values(itemResponses).reduce((acc, v) => acc + v, 0) : null;
  /* Inverted (legacy Marks 1973 direction): lower = more vivid; range 32..160.
   * Σ(6 − raw) where raw ∈ [1, 5]. */
  const vviq2InvertedTotal = complete
    ? Object.values(itemResponses).reduce((acc, v) => acc + (6 - v), 0)
    : null;
  return {
    itemResponses,
    answered,
    total: VVIQ_TOTAL_ITEMS,
    vviq2Total,
    vviq2InvertedTotal,
    complete,
  };
}
