/**
 * Credit-card screen calibration → CSS `--mm` custom property.
 *
 * Online participants have wildly different screens (laptops, monitors, hi-DPI
 * tablets), so we cannot trust CSS pixels to mean a fixed physical size. We
 * ask the participant to drag a card outline until it matches a real ID-1
 * (credit-/Prolific-payment-card) at 85.60 mm × 53.98 mm. The horizontal pixel
 * count of the matched outline gives us pixels-per-mm for that screen, which
 * we publish as `--mm` so every visual primitive (grid cells, dots, stars)
 * uses physical-size CSS rules like `width: calc(var(--mm) * 38)`.
 *
 * Reference: ISO/IEC 7810 ID-1 dimensions. Used in many web psychophysics
 * stacks (e.g., Li et al. 2020 virtual-chinrest). We do not also do
 * blind-spot distance estimation — for our 5×5 cell-grid task, accurate
 * physical size matters far more than viewing distance, and skipping the
 * blind-spot step shortens the chain.
 *
 * Retry: a wildly off px/mm (outside [1.5, 12]) almost always means the
 * participant didn't understand the task — they dragged the slider to one
 * extreme without holding a card up. We re-prompt once with a brief hint and
 * accept whatever they enter on attempt 2. After that, downstream sizing will
 * still render (just possibly mis-scaled), which is preferable to blocking the
 * session entirely on a UI step we cannot fully validate online.
 */
import htmlButtonResponse from '@jspsych/plugin-html-button-response';
import callFunction from '@jspsych/plugin-call-function';
import { registerHiddenNavStep, trackHiddenNavNode } from '../hidden-nav.js';

const CARD_MM_WIDTH = 85.6;
const PX_PER_MM_MIN = 1.5;
const PX_PER_MM_MAX = 12;
const SLIDER_MIN_PX = 100;
const SLIDER_MAX_PX = 1100;
const SLIDER_DEFAULT_PX = 320;
const DEFAULT_MAX_ATTEMPTS = 2;
const SCREEN_CALIBRATION_STEP_ID = 'screen_calibration';
const SCREEN_CALIBRATION_RETRY_STEP_ID = 'screen_calibration_retry_hint';

const HTML = `
  <h2>Calibrate the screen</h2>
  <p data-voiceover-target style="max-width: 38rem; margin: 0 auto 1rem;">
    Hold a <strong>credit card</strong> against your screen. Use the slider
    to resize the rectangle below until it exactly matches the width of the
    card.
  </p>
  <div id="cc-stage" style="margin: 1.5rem auto; height: 14rem; position: relative;">
    <div id="cc-rect"
         style="position: absolute; left: 50%; top: 1rem; transform: translateX(-50%);
                width: ${SLIDER_DEFAULT_PX}px; height: ${SLIDER_DEFAULT_PX * (53.98 / 85.6)}px; border: 2px solid #fff; border-radius: 6px;
                background: linear-gradient(135deg, #1f3a8a 0%, #1e40af 100%);">
    </div>
  </div>
  <input id="cc-slider" type="range" min="${SLIDER_MIN_PX}" max="${SLIDER_MAX_PX}" value="${SLIDER_DEFAULT_PX}"
         style="width: 24rem; max-width: 100%;" />
  <p style="opacity: 0.7; margin-top: 1rem;">
    A real card is <strong>85.6 mm</strong> wide.
  </p>
`;

const RETRY_HINT_HTML = `
  <h2>Let's try the calibration once more</h2>
  <div data-voiceover-target>
    <p style="max-width: 38rem; margin: 0 auto 1rem;">
      Your previous setting was outside the range we can use. Please make sure
      you have an actual <strong>credit card</strong> in hand. On the next
      screen, hold the card <em>flat against your monitor</em> and drag the
      slider until the on-screen rectangle matches the card's width.
    </p>
    <p style="opacity: 0.8;">If you don't have a credit card available, just continue — we will use your best estimate.</p>
  </div>
`;

function screenCalibrationTrial() {
  const node = {
    type: htmlButtonResponse,
    stimulus: HTML,
    choices: ['This matches my card'],
    on_load: () => {
      const slider = document.getElementById('cc-slider');
      const rect = document.getElementById('cc-rect');
      const update = () => {
        const px = parseInt(slider.value, 10);
        rect.style.width = `${px}px`;
        rect.style.height = `${px * (53.98 / 85.6)}px`;
      };
      slider.addEventListener('input', update);
      update();
    },
    on_finish: (data) => {
      const slider = document.getElementById('cc-slider');
      const px = slider ? parseInt(slider.value, 10) : SLIDER_DEFAULT_PX;
      const px_per_mm = px / CARD_MM_WIDTH;
      data.cc_px_width = px;
      data.px_per_mm = px_per_mm;
      data.px_per_mm_in_bounds = px_per_mm >= PX_PER_MM_MIN && px_per_mm <= PX_PER_MM_MAX;
      data.px_per_mm_min = PX_PER_MM_MIN;
      data.px_per_mm_max = PX_PER_MM_MAX;
      document.documentElement.style.setProperty('--mm', `${px_per_mm}px`);
    },
    data: { phase: 'screen_calibration' },
  };
  registerHiddenNavStep(SCREEN_CALIBRATION_STEP_ID, screenCalibrationTrial);
  return trackHiddenNavNode(node, SCREEN_CALIBRATION_STEP_ID);
}

/**
 * Sanity check: refuse pixel densities outside [1.5, 12] px/mm. The bounds
 * cover everything from a low-density 1024×768 desktop monitor up to a
 * 4K laptop panel; outside the bounds it's almost certainly a mis-calibration
 * and the loop wrapper re-prompts once.
 */
function screenCalibrationGate() {
  return {
    type: callFunction,
    async: false,
    func: () => {
      const last = window.jsPsych?.data
        ?.get()
        .filter({ phase: 'screen_calibration' })
        .last(1)
        .values()[0];
      const ok = last && last.px_per_mm >= PX_PER_MM_MIN && last.px_per_mm <= PX_PER_MM_MAX;
      return { passed: !!ok, px_per_mm: last?.px_per_mm ?? null };
    },
    data: { phase: 'screen_calibration_gate' },
  };
}

function screenCalibrationRetryHintTrial() {
  const node = {
    type: htmlButtonResponse,
    stimulus: RETRY_HINT_HTML,
    choices: ['Continue'],
    data: { phase: 'screen_calibration_retry_hint' },
  };
  registerHiddenNavStep(SCREEN_CALIBRATION_RETRY_STEP_ID, screenCalibrationRetryHintTrial);
  return trackHiddenNavNode(node, SCREEN_CALIBRATION_RETRY_STEP_ID);
}

function screenCalibrationRetryHint(attemptsRef) {
  return {
    timeline: [screenCalibrationRetryHintTrial()],
    /* Show the retry hint only on attempts beyond the first. attemptsRef
     * is mutated by `loop_function` so this conditional sees the live count. */
    conditional_function: () => attemptsRef.count >= 1,
  };
}

/**
 * Composite calibration node: cal-trial + gate, wrapped in `loop_function`
 * that re-runs the pair once on bad px/mm. After `maxAttempts` (default 2),
 * the loop exits regardless and downstream stages accept whatever value
 * was set — we do not want a single mis-clicked slider to abort the session.
 *
 * Use this in place of separate `screenCalibrationTrial()` + `screenCalibrationGate()`
 * calls from the calibration-chain composer.
 *
 * @param {object} [opts]
 * @param {number} [opts.maxAttempts]   default 2 (one retry)
 * @returns {object}                    jsPsych timeline node
 */
export function screenCalibrationWithRetry({ maxAttempts = DEFAULT_MAX_ATTEMPTS } = {}) {
  const attemptsRef = { count: 0 };
  return {
    timeline: [
      screenCalibrationRetryHint(attemptsRef),
      screenCalibrationTrial(),
      screenCalibrationGate(),
      screenCalibrationOutcome(attemptsRef, maxAttempts),
    ],
    loop_function: () => {
      attemptsRef.count += 1;
      if (attemptsRef.count >= maxAttempts) return false;
      const last = window.jsPsych?.data
        ?.get()
        .filter({ phase: 'screen_calibration_gate' })
        .last(1)
        .values()[0];
      const passed = !!last?.value?.passed;
      return !passed;
    },
  };
}

/**
 * Final summary row written after the loop. Captures `attempts_used` (1 if
 * the participant got a usable px/mm on first try, 2 if they had to retry,
 * up to maxAttempts) plus the final px_per_mm and bounds outcome — analysts
 * can spot mis-calibrated sessions without having to fold across multiple
 * `screen_calibration` rows.
 */
function screenCalibrationOutcome(attemptsRef, maxAttempts) {
  return {
    type: callFunction,
    async: false,
    func: () => {
      const lastCal = window.jsPsych?.data
        ?.get()
        .filter({ phase: 'screen_calibration' })
        .last(1)
        .values()[0];
      const px_per_mm = Number.isFinite(lastCal?.px_per_mm) ? lastCal.px_per_mm : null;
      return {
        attempts_used: attemptsRef.count,
        max_attempts: maxAttempts,
        retried: attemptsRef.count > 1,
        px_per_mm,
        px_per_mm_in_bounds: lastCal?.px_per_mm_in_bounds === true,
      };
    },
    data: { phase: 'screen_calibration_outcome' },
  };
}

/* Tests reference these constants so they can verify the locked bounds. */
export const _testHelpers = Object.freeze({
  CARD_MM_WIDTH,
  PX_PER_MM_MIN,
  PX_PER_MM_MAX,
  SLIDER_MIN_PX,
  SLIDER_MAX_PX,
  SLIDER_DEFAULT_PX,
  DEFAULT_MAX_ATTEMPTS,
});
