/**
 * Post-experiment questionnaire composer.
 *
 * Order: VVIQ-2 (32 items across 8 vignettes; Marks 1995) → music-experience
 * questionnaire (Gold-MSI Musical Training subscale + AP self-report;
 * draft revision 2026-05-07, supersedes the ad hoc 5-item set introduced in
 * the 2026-05-05 draft revision — covariate for the §3.2 non-musical
 * tone-bank redesign so the analyst can flag the absolute-pitch and
 * substantial-musical-training cases despite the bank's structural
 * non-musicality).
 *
 * Deferred to a later iteration (PLAN row 7 q7 + design §11.1):
 *   - Custom strategy questionnaire matching the archived strategy-response
 *     schema (Slide1_Q*, Slide2_Q*, Slide3_Q*, Slide4_Q* — 26 items).
 *
 * The strategy questions need careful wording reproduction from the archived
 * Persian instrument, which is open-question PLAN §7 q7. Punted until the
 * locale-lock decision is made; the analysis pipeline already treats
 * `feedback_results.csv` as optional (Supplementary S4 in the OSF analysis).
 */
import htmlKeyboardResponse from '@jspsych/plugin-html-keyboard-response';
import { vviqTimeline } from './vviq.js';
import { musicExperienceTimeline } from './music-experience.js';
import { registerHiddenNavStep, trackHiddenNavNode } from '../hidden-nav.js';

function questionnaireIntro() {
  const stepId = 'questionnaire_intro';
  const node = {
    type: htmlKeyboardResponse,
    stimulus: `
      <div style="max-width: 38rem; margin: 0 auto; text-align: left;">
        <h2 style="text-align: center;">One last set of questions</h2>
        <p>You have finished the main task — thank you. Before we save your
        data, we have two short questionnaires:</p>
        <ol>
          <li>A <strong>visual imagery</strong> questionnaire — eight short
          scene descriptions, with vividness ratings for some specific
          details (about 8–10 minutes).</li>
          <li>A <strong>music background</strong> questionnaire — five quick
          questions about your music training and listening (about 1 minute).</li>
        </ol>
        <p>There are no right or wrong answers; people differ widely on both
        of these dimensions, and that is exactly what we want to measure.</p>
        <p style="text-align: center; margin-top: 1.5rem;">
          Press <kbd>Space</kbd> to begin.
        </p>
      </div>
    `,
    choices: [' '],
    data: { phase: 'questionnaire_intro' },
  };
  registerHiddenNavStep(stepId, questionnaireIntro);
  return trackHiddenNavNode(node, stepId);
}

export function assembleQuestionnaireChain() {
  return [questionnaireIntro(), ...vviqTimeline(), ...musicExperienceTimeline()];
}
