/**
 * Top-level jsPsych timeline assembly — design §11 + agent prompt §5/§12.
 *
 * Session flow:
 *   1. Calibration chain (Step 3).
 *   2. Post-calibration readiness + 10 random-frequency tones (1 s each,
 *      200 ms gaps, drawn uniformly on [500 Hz, 2000 Hz]) immediately before
 *      instructions.
 *   3. Instructions + interleaved per-type practice (Step 11): each task's
 *      teaching screen is followed immediately by that task's practice
 *      trials; three typed-instruction attention checks (§11.4) sit at the
 *      boundaries of the memory / imagery / dual teaching arcs. The whole
 *      block is wrapped in a single jsPsych `loop_function` gated on
 *      cumulative practice accuracy versus §11.3's criterion (= 0.7), with
 *      one re-loop allowed.
 *   4. Main A (Step 9): 60 trials (12 × 5 types).
 *   5. Inter-block rest (Step 9): 60 s forced countdown.
 *   6. Main B (Step 9): 60 trials (12 × 5 types).
 *   7. Questionnaire chain (Step 11): VVIQ-2 (Marks 1995, 32 items / 8 vignettes).
 *   8. Upload (Step 10): chunked POST of pending rows from IndexedDB to the
 *      configured server endpoint, with retry/backoff + JSON-download
 *      fallback.
 *   9. Completion redirect (Step 10): countdown then `window.location.href`
 *      to the Prolific completion URL (or test-build notice if the URL is
 *      still the placeholder).
 *
 * The visual-primitives demo (`src/visuals/demo.js`) is intentionally NOT in
 * the production timeline — it exposes raw stimuli before any instructional
 * context. It remains accessible at `/dev-main.html` (Step 13) for developer
 * inspection.
 *
 * Each per-trial data row is mirrored into IndexedDB on `on_data_update` so
 * a participant who crashes the browser mid-session loses at most the
 * in-flight trial (agent prompt §5). The Prolific completion URL is also
 * persisted at session start (agent prompt §12) so the participant can
 * retrieve it manually if the network is down at completion time.
 */
import { initJsPsych } from 'jspsych';
import htmlKeyboardResponse from '@jspsych/plugin-html-keyboard-response';

import { config } from './config.js';
import { initSession } from './prolific.js';
import { assembleCalibrationChain } from './calibration/index.js';
import { assembleReadyRandomTonesTimeline } from './calibration/ready-random-tones.js';
import { getVisibilityEvents } from './calibration/fullscreen.js';
import { generateMainBlockPair } from './scheduler/main-blocks.js';
import { restNode } from './conditions/rest.js';
import { uploadProgressNode, completionRedirectNode } from './conditions/debrief.js';
import { unmountTrialCounter } from './conditions/trial-counter.js';
import { initStorage, appendTrialRow, recordWriteFailure } from './storage.js';
import { assembleInstructionsAndPractice } from './instructions/index.js';
import { assembleQuestionnaireChain } from './questionnaire/index.js';
import {
  installHiddenNav,
  registerHiddenNavStep,
  trackHiddenNavNode,
  getHiddenNavTrialStartHook,
} from './hidden-nav.js';
import { getToneBank } from './audio/tones.js';
import { installVoiceoverSlideObserver } from './visuals/voiceover-slide.js';

const session = initSession();

/* Storage init runs in parallel with the rest of module load. The first
 * jsPsych trial doesn't fire data hooks until the user starts the timeline,
 * so by then init is complete. We capture the promise here to await it
 * before `jsPsych.run` if needed. */
const storageReadyPromise = initStorage();

/* Warm any lazily-built assets at module load so no main-block trial pays a
 * first-touch cost.
 *   - Tone bank: `getToneBank()` builds the analytic cell↔tone maps in
 *     `audio/tones.js` (cached after first call). Without this, the first
 *     `playToneByCell` of the session would build the maps on its hot path.
 *     The familiarisation screen plays a frequency ladder via `dsp.js` and
 *     does not exercise the cell-keyed bank, so it does not warm this for us.
 *   - Rotation arrow PNG: kick off the network fetch now via an offscreen
 *     `Image()` so the browser cache is warm before the first imagery
 *     instruction demo (and therefore well before the first main trial).
 *     The literal URL matches `visuals/rotation-arrow.js` and the other
 *     consumers — this is a fetch-warmer, not a new asset reference. */
function warmupAssets() {
  getToneBank();
  if (typeof Image !== 'undefined') {
    const img = new Image();
    img.src = `${import.meta.env.BASE_URL}assets/rotation-arrow.png`;
  }
}
warmupAssets();

const jsPsych = initJsPsych({
  display_element: undefined,
  /* Hidden-nav skip-forward hook: when the experimenter presses `U` from
   * inside a non-checkpoint trial, the keydown handler in `hidden-nav.js`
   * arms a skip token; this hook neutralises every following non-checkpoint
   * trial (zero duration, no input) until the next registered checkpoint
   * (instructions / demo / intro). Without this hook, `U` from a trial
   * would only advance one trial. */
  on_trial_start: getHiddenNavTrialStartHook(),
  on_data_update: (datum) => {
    /* Mirror every data row into IndexedDB so the participant can crash the
     * browser at any point without losing more than the in-flight trial
     * (agent prompt §5). Fire-and-forget — appendTrialRow throws on
     * unrecoverable backend failure, which we surface to the console; the
     * participant can still finish the session because the data is also held
     * in jsPsych's in-memory store and gets uploaded at the end. */
    appendTrialRow(datum).catch((err) => {
      console.error('[runner] storage append failed', err);
      recordWriteFailure(err);
    });
  },
  on_finish: () => {
    /* Stamp session-level metadata onto every row for the analyst. Upload
     * already ran in the upload-progress node; this just adds session-wide
     * fields to whatever's still in memory (in case the experimenter copies
     * out the in-memory data via `jsPsych.data.get()` for debugging). */
    const data = jsPsych.data?.get?.();
    if (data && typeof data.addProperties === 'function') {
      data.addProperties({
        session_id: session.params.session_id,
        prolific_pid: session.params.prolific_pid,
        study_id: session.params.study_id,
        is_preview: session.params.is_preview,
        is_pilot_run: session.is_pilot_run,
        pilot_label: session.pilot_label,
        prng_seed_uint32: session.prng_seed_uint32,
        schema_version: session.schema_version,
        build_id: session.build_id,
      });
    }
    console.info('[runner] session', session, 'visibility', getVisibilityEvents());
  },
});
window.jsPsych = jsPsych;

/* Hidden experimenter navigation — `U` advances the current registered
 * screen and `R` takes one registered screen back. */
installHiddenNav(jsPsych);

/* Voiceover slide-narration observer — mounts before the first
 * instruction-style slide is rendered. The observer watches
 * `document.body` for `[data-voiceover-target]` nodes (stamped by
 * `slideTextPage` in `src/visuals/slide-layout.js`) and hands each new
 * one to the engine for word-synced narration. The mute pill mounts
 * itself on the first narrated slide and is torn down by the
 * trial-start gate's `on_load` so it doesn't bleed into trial bodies.
 * Idempotent — safe to call once at session start. */
installVoiceoverSlideObserver();

function mainAIntroNode() {
  const stepId = 'main_a_intro';
  const node = {
    type: htmlKeyboardResponse,
    stimulus: `
      <div style="max-width: 36rem; margin: 0 auto;">
        <h2>Main task — Block 1 of 2</h2>
        <div data-voiceover-target>
          <p>Now the main task begins. There are two blocks of 60 trials. Each
          block includes a ${config.blocks.rest_duration_s}-second rest after
          trials 20 and 40, and there is another
          ${config.blocks.rest_duration_s}-second rest between the two blocks.</p>
          <p>Same controls as the practice: <strong>Yes</strong> /
          <strong>On-pattern</strong> on one response key,
          <strong>No</strong> / <strong>Not on-pattern</strong> on the
          other.</p>
          <p>Press <kbd>Space</kbd> to begin Block 1.</p>
        </div>
      </div>
    `,
    choices: [' '],
    data: { phase: 'main_a_intro' },
  };
  registerHiddenNavStep(stepId, mainAIntroNode);
  return trackHiddenNavNode(node, stepId);
}

function mainBIntroNode() {
  const stepId = 'main_b_intro';
  const node = {
    type: htmlKeyboardResponse,
    stimulus: `
      <div style="max-width: 36rem; margin: 0 auto;">
        <h2>Main task — Block 2 of 2</h2>
        <div data-voiceover-target>
          <p>Last block. 60 more trials, same controls, with
          ${config.blocks.rest_duration_s}-second rests after trials 20
          and 40.</p>
          <p>Press <kbd>Space</kbd> to begin Block 2.</p>
        </div>
      </div>
    `,
    choices: [' '],
    data: { phase: 'main_b_intro' },
  };
  registerHiddenNavStep(stepId, mainBIntroNode);
  return trackHiddenNavNode(node, stepId);
}

function endOfTaskIntroNode() {
  const stepId = 'end_of_task_intro';
  const node = {
    type: htmlKeyboardResponse,
    stimulus: `
      <div style="max-width: 36rem; margin: 0 auto;">
        <h2>You've finished the task</h2>
        <div data-voiceover-target>
          <p>Thank you for completing the experiment. We'll save your data now —
          this usually takes a few seconds.</p>
          <p>Press <kbd>Space</kbd> to continue.</p>
        </div>
      </div>
    `,
    choices: [' '],
    data: { phase: 'end_of_task_intro' },
    on_load: () => {
      /* Main task is over — remove the dim "Trial X / 120" overlay so it
       * doesn't bleed into the questionnaire chain. */
      unmountTrialCounter();
    },
  };
  registerHiddenNavStep(stepId, endOfTaskIntroNode);
  return trackHiddenNavNode(node, stepId);
}

const mainPair = generateMainBlockPair();

const timeline = [
  ...assembleCalibrationChain(),
  ...assembleReadyRandomTonesTimeline(),
  ...assembleInstructionsAndPractice(),
  mainAIntroNode(),
  ...mainPair.mainA.nodes,
  restNode(),
  mainBIntroNode(),
  ...mainPair.mainB.nodes,
  endOfTaskIntroNode(),
  ...assembleQuestionnaireChain(),
  uploadProgressNode({ session }),
  completionRedirectNode(),
];

/* If IDB open fails fatally we'd otherwise sit on a blank screen forever —
 * `initStorage` already falls back to the in-memory backend on a recoverable
 * error, so a rejected promise here means something has gone genuinely wrong
 * (browser blocking storage entirely, etc.). Surface a fatal error UI rather
 * than starting a session whose data we can't persist. */
storageReadyPromise
  .then(() => jsPsych.run(timeline))
  .catch((err) => {
    console.error('[runner] fatal startup failure', err);
    const root = document.body;
    root.innerHTML = `
      <div style="max-width: 36rem; margin: 4rem auto; padding: 2rem; text-align: center;">
        <h2>Unable to start the experiment</h2>
        <p>Your browser is blocking the local storage this study needs. Please
        try a different browser (Chrome, Firefox, or Safari) on a desktop or
        laptop computer, with private/incognito mode disabled.</p>
        <p><small>Error reference: <code>${(err && err.message) || 'unknown'}</code></small></p>
      </div>
    `;
  });
